command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: HUSTEN UND JUCKEN (Aphasma)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (!globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }
    if (!globalThis.DSK) return ui.notifications.error("Das DSK-Framework fehlt!");
    const DSK_FW = globalThis.DSK; 

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. WIRKENDEN PRÜFEN & QS HOLEN ---
    let casterToken = canvas.tokens.controlled[0];
    const casterActor = casterToken?.actor || game.user.character;
    if (!casterActor) return ui.notifications.warn("Bitte wähle zuerst deinen Token aus!");

    if (!casterToken) casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) await casterActor.unsetFlag("world", "letzteGabenQS"); 
    if (typeof testData !== "undefined" && testData) qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);

    const gabenName = "Husten und Jucken";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const dauerMinuten = qsWert * 2;
    const reichweite = 4;
    const iconBild = DSK_FW.Symbol(ahne);

    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. ZIEL PRÜFEN ---
    let targetToken = game.user.targets.first();
    if (!targetToken) return ui.notifications.warn("Bitte markiere (Target) zuerst das Token deines Ziels!");

    let targetActor = targetToken.actor;
    if (!targetActor) return ui.notifications.warn("Das gewählte Ziel hat keinen gültigen Charakterbogen!");

    // Distanz prüfen (4 Schritt)
    if (casterToken && targetToken && DSK_FW.Distanz) {
        const dist = DSK_FW.Distanz(casterToken, targetToken);
        if (dist > reichweite) {
            return ui.notifications.warn(`Ziel verfehlt! ${targetToken.name} ist zu weit entfernt! (Distanz: ${Math.round(dist)} Schritt)`);
        }
    }

    // --- 4. MENSCHEN-PRÜFUNG ---
    const species = (targetActor.system?.species?.value || targetActor.system?.details?.species || "").toLowerCase();
    const isMensch = species.includes("mensch") || species.includes("human");

    if (!isMensch) {
        return ChatMessage.create({
            speaker: { alias: "System" },
            whisper: whisperTargets,
            content: `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                    <div class="dskbox2" style="margin-top:10px; text-align:center;">
                        <p style="color:#b30000; font-weight:bold; font-size:1.1em;">Wirkung verpufft!</p>
                        <p><b>${targetActor.name}</b> ist kein Mensch (Spezies: ${targetActor.system?.species?.value || "Unbekannt"}).</p>
                        <p style="font-size:0.9em; color:#555; margin-top:8px;"><i>Die magische Katzenhaarallergie läuft völlig ins Leere. Die AeP wurden dennoch verbraucht.</i></p>
                    </div>
                </div>
            `
        });
    }

    // --- 5. SYMPTOME ANHAND QS BERECHNEN ---
    let symptomListe = ["gerötete Augen", "juckende Nase"];
    if (qsWert >= 2) symptomListe.push("laufende Nase", "starker Niesreiz");
    if (qsWert >= 3) symptomListe.push("Atemschwierigkeiten");
    if (qsWert >= 4) symptomListe.push("starker Juckreiz");
    if (qsWert >= 5) symptomListe.push("Ausschlag");
    if (qsWert >= 6) {
        symptomListe = symptomListe.filter(s => s !== "Ausschlag");
        symptomListe.push("starker Ausschlag mit roten Pusteln");
    }
    const symptomText = symptomListe.join(", ");

    // --- 6. 🚩 ENDEKARTE REGISTRIEREN ---
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("hustenUndJucken", finalEffektName, "Die magische Katzenhaarallergie klingt ab. Das Niesen hört auf und das Ziel kann wieder frei atmen.");
    }

    // --- 7. EFFEKT AUF DAS ZIEL ANWENDEN ---
    let oldEff = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (oldEff) await oldEff.delete();

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        description: `Das Ziel leidet unter einer heftigen magischen Katzenhaarallergie.<br><b>Symptome:</b> ${symptomText}`,
        duration: { seconds: dauerMinuten * 60 },
        changes: [
            { key: "system.skillModifiers.global", mode: 2, value: -qsWert }
        ],
        flags: { 
            dsk: { 
                value: qsWert, 
                max: 6, 
                casterUuid: casterActor.uuid 
            } 
        }
    }]);

    // --- 8. ÖFFENTLICHE CHAT-KARTE ---
    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="margin-bottom: 8px;"><b>${casterName}</b> webt einen Fluch gegen <b>${targetActor.name}</b>!</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">
                        Das Ziel wird schlagartig von den Symptomen einer extremen Katzenhaarallergie übermannt.
                    </p>
                    <p style="margin-bottom: 8px; color:#8b0000;">
                        <b>Symptome:</b><br>${symptomText}
                    </p>
                    <p style="margin-bottom: 8px; font-weight:bold; font-size:1.1em;">
                        Abzug von -${qsWert} auf alle Proben!
                    </p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten (QS ${qsWert})</p>
                </div>
            </div>
        `
    });

})();
